#include <stdio.h>

int main(void) {
    unsigned int n;
    if (scanf("%u", &n) != 1) return 1;
    /* mov eax, imm32 (B8 + 4 byte little-endian), rồi ret (C3) */
    printf("B8 %02X %02X %02X %02X C3\n",
           n & 0xFF, (n >> 8) & 0xFF, (n >> 16) & 0xFF, (n >> 24) & 0xFF);
    return 0;
}
